files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b1e3a;
  --card-bg: #fff8e7;
  --crust-color: #d97724;
  --cheese-color: #f6c445;
  --text-main: #231911;
  --accent-red: #d13438;
  --accent-shadow: #8c1e21;
  --border-dark: #1b130e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.app-container {
  width: 100%;
  max-width: 440px;
}

.pizza-card {
  background-color: var(--card-bg);
  border: 4px solid var(--border-dark);
  box-shadow: 8px 8px 0px var(--border-dark);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.card-header {
  text-align: center;
}

.title {
  font-size: 26px;
  letter-spacing: 2px;
  color: var(--accent-red);
  text-shadow: 2px 2px 0 var(--border-dark);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 14px;
  font-weight: bold;
  color: #5d4037;
}

.pizza-display {
  display: flex;
  justify-content: center;
  align-items: center;
  background: #f1ebd9;
  border: 3px solid var(--border-dark);
  padding: 12px;
}

#pizzaCanvas {
  image-rendering: pixelated;
  background: transparent;
}

.section-group {
  border: 2px dashed var(--border-dark);
  padding: 12px;
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-label {
  font-weight: bold;
  padding: 0 4px;
  font-size: 15px;
}

.size-selector {
  display: flex;
  gap: 8px;
  justify-content: space-between;
}

.size-option {
  flex: 1;
  position: relative;
  cursor: pointer;
}

.size-option input[type="radio"],
.topping-option input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  cursor: pointer;
  margin: 0;
}

.pixel-btn,
.topping-btn {
  display: block;
  text-align: center;
  padding: 8px 4px;
  border: 2px solid var(--border-dark);
  background: #ffffff;
  font-size: 14px;
  font-weight: bold;
  box-shadow: 2px 2px 0 var(--border-dark);
  user-select: none;
}

.size-option input[type="radio"]:hover + .pixel-btn,
.topping-option input[type="checkbox"]:hover + .topping-btn {
  background: #fff3c4;
}

.size-option input[type="radio"]:focus-visible + .pixel-btn,
.topping-option input[type="checkbox"]:focus-visible + .topping-btn {
  outline: 3px solid var(--accent-red);
  outline-offset: 1px;
}

.size-option input[type="radio"]:checked + .pixel-btn,
.topping-option input[type="checkbox"]:checked + .topping-btn {
  background: var(--cheese-color);
  box-shadow: inset 2px 2px 0 var(--border-dark);
  transform: translate(2px, 2px);
}

.toppings-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.topping-option {
  position: relative;
  cursor: pointer;
}

.error-banner {
  background-color: var(--accent-red);
  color: #ffffff;
  padding: 8px;
  text-align: center;
  font-weight: bold;
  border: 2px solid var(--border-dark);
  box-shadow: 2px 2px 0 var(--border-dark);
  font-size: 14px;
}

.price-banner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 20px;
  font-weight: bold;
  border-top: 3px solid var(--border-dark);
  padding-top: 12px;
  margin-bottom: 16px;
}

.price-tag {
  color: var(--accent-red);
  font-size: 24px;
}

.order-btn,
.reset-btn {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  color: #ffffff;
  background-color: var(--accent-red);
  border: 3px solid var(--border-dark);
  box-shadow: 4px 4px 0 var(--border-dark);
  cursor: pointer;
}

.order-btn:hover,
.reset-btn:hover {
  background-color: #b5292d;
}

.order-btn:focus-visible,
.reset-btn:focus-visible {
  outline: 3px solid #000000;
  outline-offset: 2px;
}

.order-btn:active,
.reset-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--border-dark);
}

.order-summary {
  background: #e6f4ea;
  border: 3px solid var(--border-dark);
  box-shadow: 4px 4px 0 var(--border-dark);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.summary-heading {
  font-size: 18px;
  color: #137333;
  border-bottom: 2px dashed #137333;
  padding-bottom: 4px;
}

.summary-text {
  line-height: 1.5;
  font-size: 15px;
  white-space: pre-line;
}

.reset-btn {
  background-color: #1b130e;
  font-size: 14px;
  padding: 8px;
}

document.addEventListener('DOMContentLoaded', () => {
  const pizzaForm = document.getElementById('pizzaForm');
  const sizeInputs = document.querySelectorAll('input[name="pizzaSize"]');
  const toppingInputs = document.querySelectorAll('input[name="topping"]');
  const totalPriceEl = document.getElementById('totalPrice');
  const errorMessageEl = document.getElementById('errorMessage');
  const orderSummaryEl = document.getElementById('orderSummary');
  const summaryDetailsEl = document.getElementById('summaryDetails');
  const newOrderBtn = document.getElementById('newOrderBtn');
  const canvas = document.getElementById('pizzaCanvas');
  const ctx = canvas.getContext('2d');

  const TOPPING_PRICE = 1.5;
  const MAX_TOPPINGS = 5;

  function getSelectedSize() {
    const checked = document.querySelector('input[name="pizzaSize"]:checked');
    return {
      name: checked ? checked.value : 'Small',
      price: checked ? parseFloat(checked.dataset.price) : 8
    };
  }

  function getSelectedToppings() {
    return Array.from(toppingInputs)
      .filter((input) => input.checked)
      .map((input) => input.value);
  }

  function updatePrice() {
    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    const total = size.price + (toppings.length * TOPPING_PRICE);
    totalPriceEl.textContent = `$${total.toFixed(2)}`;
    renderPizza();
  }

  function renderPizza() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const size = getSelectedSize().name;
    const toppings = getSelectedToppings();

    const radiusMap = { Small: 48, Medium: 60, Large: 72 };
    const r = radiusMap[size] || 48;
    const cx = canvas.width / 2;
    const cy = canvas.height / 2;

    // Crust
    ctx.fillStyle = '#d97724';
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.fill();

    // Cheese
    ctx.fillStyle = '#f6c445';
    ctx.beginPath();
    ctx.arc(cx, cy, r - 8, 0, Math.PI * 2);
    ctx.fill();

    // Sauce spots
    ctx.fillStyle = '#c0392b';
    for (let i = 0; i < 4; i++) {
      const angle = (i * Math.PI) / 2;
      const spotR = (r - 16) * 0.45;
      ctx.fillRect(cx + Math.cos(angle) * spotR - 3, cy + Math.sin(angle) * spotR - 3, 6, 6);
    }

    // Toppings pixel stamps
    toppings.forEach((topping, index) => {
      const count = 4;
      for (let i = 0; i < count; i++) {
        const angle = (index * 1.3) + (i * ((Math.PI * 2) / count));
        const dist = ((r - 20) * ((i % 2 === 0 ? 0.35 : 0.75)));
        const x = Math.round(cx + Math.cos(angle) * dist);
        const y = Math.round(cy + Math.sin(angle) * dist);

        if (topping === 'Pepperoni' || topping === 'Bacon') {
          ctx.fillStyle = '#a91b0d';
          ctx.fillRect(x - 4, y - 4, 8, 8);
        } else if (topping === 'Mushrooms') {
          ctx.fillStyle = '#8d6e63';
          ctx.fillRect(x - 3, y - 3, 6, 6);
        } else if (topping === 'Bell Peppers') {
          ctx.fillStyle = '#2e7d32';
          ctx.fillRect(x - 4, y - 2, 8, 4);
        } else if (topping === 'Onions') {
          ctx.fillStyle = '#e1bee7';
          ctx.fillRect(x - 3, y - 3, 6, 6);
        } else if (topping === 'Olives') {
          ctx.fillStyle = '#212121';
          ctx.fillRect(x - 3, y - 3, 6, 6);
        } else if (topping === 'Pineapple') {
          ctx.fillStyle = '#ffeb3b';
          ctx.fillRect(x - 3, y - 3, 6, 6);
        } else {
          ctx.fillStyle = '#fff9c4';
          ctx.fillRect(x - 3, y - 3, 6, 6);
        }
      }
    });
  }

  sizeInputs.forEach((input) => {
    input.addEventListener('change', () => {
      updatePrice();
    });
  });

  toppingInputs.forEach((input) => {
    input.addEventListener('change', (e) => {
      const checkedToppings = document.querySelectorAll('input[name="topping"]:checked');
      if (checkedToppings.length > MAX_TOPPINGS) {
        e.target.checked = false;
        errorMessageEl.hidden = false;
      } else {
        errorMessageEl.hidden = true;
      }
      updatePrice();
    });
  });

  pizzaForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const size = getSelectedSize();
    const toppings = getSelectedToppings();
    const total = (size.price + toppings.length * TOPPING_PRICE).toFixed(2);

    const toppingsText = toppings.length > 0 ? toppings.join(', ') : 'None';
    summaryDetailsEl.textContent = `Size: ${size.name} ($${size.price.toFixed(2)})\nToppings (${toppings.length}/5): ${toppingsText}\nTotal Due: $${total}`;

    orderSummaryEl.hidden = false;
    orderSummaryEl.scrollIntoView({ behavior: 'smooth' });
  });

  newOrderBtn.addEventListener('click', () => {
    pizzaForm.reset();
    errorMessageEl.hidden = true;
    orderSummaryEl.hidden = true;
    updatePrice();
  });

  updatePrice();
});
